  if(crop){frame.style.aspectRatio=String(asset.width*crop.width/(asset.height*crop.height));image.style.width=(100/crop.width)+'%';image.style.left=(-100*crop.x/crop.width)+'%';image.style.top=(-100*crop.y/crop.height)+'%';}
