  const key='rangers-pulse-v1-'+scope,remote=Boolean(globalThis.google?.script?.run),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
