  const selected=()=>records.filter(r=>r.player===$('pulse-player').value).sort((a,b)=>b.session_date.localeCompare(a.session_date));
  const value=(r,key)=>r?.[key]===null||r?.[key]===undefined?'—':String(r[key]);
