   const cycle=progress.unlocked_cycle,week=workoutUnlockedWeek(cycle,progress),next=WORKOUT_TRAINING_DAYS.find(d=>!workoutDayCoverage(cycle,week,d.day).every(id=>progress.completed.has(id)));
